const fs = require('fs-extra');
const path = require('path');
const os = require('os');

const {
  CLEANUP_PATH,
  customClaudeContent,
  collectCleanupItems,
  writeCleanupFile,
} = require('../../lib/utils/upgrade-cleanup');
const { renderHeadlineBlock } = require('../../lib/utils/headline');

const MARKER =
  '<!-- Generated by ContextKit (@nolrm/contextkit) https://www.npmjs.com/package/@nolrm/contextkit -->';
const MARKER_END = '<!-- End ContextKit -->';

describe('upgrade-cleanup', () => {
  let tmpDir;

  beforeEach(async () => {
    tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), 'contextkit-cleanup-'));
  });

  afterEach(async () => {
    await fs.remove(tmpDir);
  });

  it('1. customClaudeContent ignores the ContextKit and headline blocks', () => {
    const content = `${MARKER}\n@AGENTS.md\n${MARKER_END}\n\n${renderHeadlineBlock()}\n`;
    expect(customClaudeContent(content)).toBe('');
  });

  it('2. customClaudeContent returns text the user wrote', () => {
    const content = `# Team\n\n- rule\n\n${MARKER}\n@AGENTS.md\n${MARKER_END}\n`;
    expect(customClaudeContent(content)).toBe('# Team\n\n- rule');
  });

  it('3. a clean 2.0 project has nothing to clean up', async () => {
    await fs.writeFile(path.join(tmpDir, 'CLAUDE.md'), `${MARKER}\n@AGENTS.md\n${MARKER_END}\n`);
    expect(await collectCleanupItems(tmpDir)).toEqual([]);
  });

  it('4. lists squad, spec, squad CI, and pending standards updates', async () => {
    await fs.ensureDir(path.join(tmpDir, '.contextkit/squad'));
    await fs.ensureDir(path.join(tmpDir, '.contextkit/spec'));
    await fs.ensureDir(path.join(tmpDir, '.github/workflows'));
    await fs.writeFile(path.join(tmpDir, '.github/workflows/squad-issue.yml'), 'x');
    await fs.writeFile(
      path.join(tmpDir, '.contextkit/config.yml'),
      'pending_standards_updates:\n  - file: x\n    id: y\n'
    );
    const ids = (await collectCleanupItems(tmpDir)).map((i) => i.id);
    expect(ids).toEqual([
      'squad-handoff',
      'spec-folder',
      'squad-ci-workflow',
      'pending-standards-updates',
    ]);
  });

  it('5. writeCleanupFile writes the list, then removes the file once resolved', async () => {
    await fs.ensureDir(path.join(tmpDir, '.contextkit/squad'));
    await writeCleanupFile(tmpDir);
    expect(await fs.pathExists(path.join(tmpDir, CLEANUP_PATH))).toBe(true);

    await fs.remove(path.join(tmpDir, '.contextkit/squad'));
    await writeCleanupFile(tmpDir);
    expect(await fs.pathExists(path.join(tmpDir, CLEANUP_PATH))).toBe(false);
  });
});
